  display: none;
  font-size: 0.8125rem;
  color: var(--color-error);
  font-weight: 500;
  line-height: 1.4;
}
.field-error.visible {
  display: block;
}

/* ============================================================
   Submit button
   ============================================================ */
.submit-btn {
  margin-top: 0.5rem;
  width: 100%;
  padding: 0.8125rem 1.5rem;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
