 * Contact form — validation and submission logic.
 *
 * Behaviour:
 *  - No inline validation on initial render.
 *  - On submit: validate, show per-field errors, focus first invalid field.
 *  - On success: hide form, show live-region success message.
 */

(function () {
  'use strict';

  const form       = document.getElementById('contact-form');
  const successEl  = document.getElementById('form-success-msg');

  // ── Field descriptors ─────────────────────────────────────────────────────
  const fields = [
    {
      id:       'full-name',
      errorId:  'full-name-error',
      validate: (val) => val.trim().length > 0,
      message:  'Error: Please enter your full name.',
    },
    {
      id:       'email',
      errorId:  'email-error',
      validate: (val) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val.trim()),
      message:  'Error: Enter a valid email address (e.g., name@example.com).',
    },
    // Phone is optional — only validate format if a value is provided.
    {
      id:       'phone',
      errorId:  'phone-error',
      validate: (val) => {
        if (val.trim() === '') return true;
        // Accept digits, spaces, hyphens, parentheses, plus sign — at least 7 digits.
        const digitsOnly = val.replace(/\D/g, '');
        return digitsOnly.length >= 7 && digitsOnly.length <= 15;
      },
      message:  'Error: Enter a valid phone number (e.g., +1 (555) 000-0000).',
    },
  ];

  // ── Helpers ───────────────────────────────────────────────────────────────
  function getInput(fieldDef) {
    return document.getElementById(fieldDef.id);
  }

  function getErrorEl(fieldDef) {
    return document.getElementById(fieldDef.errorId);
  }

  function markInvalid(fieldDef) {
    const input = getInput(fieldDef);
    const errorEl = getErrorEl(fieldDef);
    input.setAttribute('aria-invalid', 'true');
    errorEl.textContent = fieldDef.message;
    errorEl.classList.add('visible');
  }

  function markValid(fieldDef) {
    const input = getInput(fieldDef);
    const errorEl = getErrorEl(fieldDef);
    input.removeAttribute('aria-invalid');
    errorEl.textContent = '';
    errorEl.classList.remove('visible');
  }

  // ── Live validation after first-submit (per-field, on blur/input) ─────────
  function attachLiveValidation(fieldDef) {
    const input = getInput(fieldDef);

    // Validate on blur after the user has interacted.
    input.addEventListener('blur', () => {
      if (!input.dataset.touched) return;
      if (!fieldDef.validate(input.value)) {
        markInvalid(fieldDef);
      } else {
        markValid(fieldDef);
      }
    });

    // Clear error eagerly as the user corrects the field.
    input.addEventListener('input', () => {
      if (!input.dataset.touched) return;
      if (fieldDef.validate(input.value)) {
        markValid(fieldDef);
      }
    });

    // Mark as touched once the user has left the field at least once.
    input.addEventListener('blur', () => {
      input.dataset.touched = 'true';
    }, { once: true });
  }

  fields.forEach(attachLiveValidation);

  // ── Submit handler ────────────────────────────────────────────────────────
  form.addEventListener('submit', (event) => {
    event.preventDefault();

    // Mark all fields as touched so live validation works from here on.
    fields.forEach((f) => {
      getInput(f).dataset.touched = 'true';
    });

    // Run validation and collect failures.
    const invalidFields = fields.filter((f) => {
      const input = getInput(f);
      const valid = f.validate(input.value);
      if (!valid) {
        markInvalid(f);
      } else {
        markValid(f);
      }
      return !valid;
    });

    if (invalidFields.length > 0) {
      // Move focus to the first invalid field (WCAG 3.3.1 / forms.md).
      getInput(invalidFields[0]).focus();
      return;
    }

    // ── Simulate async submission ──────────────────────────────────────────
    const submitBtn = form.querySelector('.submit-btn');
    submitBtn.disabled = true;
    submitBtn.textContent = 'Sending…';

    setTimeout(() => {
      // Hide the form visually (keep in DOM so focus doesn't break).
      form.hidden = true;

      // Announce success via pre-rendered live region.
      successEl.textContent = '✓ Message sent! We'll be in touch soon.';
      successEl.classList.add('visible');
    }, 800);
